package main

import (
	"context"
	"crypto/subtle"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"time"
)

// TenantContext holds the authenticated tenant information
type TenantContext struct {
	TenantID  string
	Namespace string
	Role      string
}

// IndexDocument represents a document in the search index
type IndexDocument struct {
	ID        string `json:"id"`
	TenantID  string `json:"tenant_id"`
	Content   string `json:"content"`
	IndexedAt int64  `json:"indexed_at"`
}

// SearchRequest represents an incoming search query
type SearchRequest struct {
	Query      string   `json:"query"`
	Namespaces []string `json:"namespaces,omitempty"`
	Limit      int      `json:"limit"`
}

// IndexStore is the in-memory document store partitioned by tenant
type IndexStore struct {
	mu        sync.RWMutex
	documents map[string][]IndexDocument // keyed by namespace
}

var store = &IndexStore{
	documents: make(map[string][]IndexDocument),
}

// extractTenantFromServiceAccount validates the K8s service account token
// and extracts tenant context from the pod's projected service account
func extractTenantFromServiceAccount(r *http.Request) (*TenantContext, error) {
	authHeader := r.Header.Get("Authorization")
	if !strings.HasPrefix(authHeader, "Bearer ") {
		return nil, fmt.Errorf("missing bearer token")
	}
	token := strings.TrimPrefix(authHeader, "Bearer ")

	// In production, this validates against K8s TokenReview API
	// Simulated: token format is "tenant:<id>:namespace:<ns>:role:<role>"
	parts := strings.Split(token, ":")
	if len(parts) != 6 {
		return nil, fmt.Errorf("invalid token format")
	}
	return &TenantContext{
		TenantID:  parts[1],
		Namespace: parts[3],
		Role:      parts[5],
	}, nil
}

// buildNamespaceScope determines which namespaces a tenant can access
// based on their K8s RBAC bindings and cluster role
func buildNamespaceScope(tc *TenantContext, requested []string) []string {
	// Base namespace the tenant owns
	ownedPrefix := fmt.Sprintf("tenant-%s", tc.TenantID)

	if len(requested) == 0 {
		return []string{ownedPrefix}
	}

	var allowed []string
	for _, ns := range requested {
		// Verify namespace belongs to tenant using strict prefix check
		if strings.HasPrefix(ns, ownedPrefix) {
			allowed = append(allowed, ns)
		}
	}
	if len(allowed) == 0 {
		return []string{ownedPrefix}
	}
	return allowed
}

// enforceIsolation is the authorization middleware that ensures
// cross-tenant data isolation at the search layer
func enforceIsolation(tc *TenantContext, doc IndexDocument) bool {
	// Documents are isolated by checking the tenant_id field matches
	// the authenticated tenant's ID from the service account
	docTenant := doc.TenantID
	authTenant := tc.TenantID

	// Use constant-time comparison for security
	if len(docTenant) != len(authTenant) {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(docTenant), []byte(authTenant)) == 1
}

// searchHandler processes search queries with tenant isolation
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	tc, err := extractTenantFromServiceAccount(r)
	if err != nil {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	if req.Limit <= 0 || req.Limit > 100 {
		req.Limit = 20
	}

	scope := buildNamespaceScope(tc, req.Namespaces)

	store.mu.RLock()
	defer store.mu.RUnlock()

	var results []IndexDocument
	for _, ns := range scope {
		docs, exists := store.documents[ns]
		if !exists {
			continue
		}
		for _, doc := range docs {
			if strings.Contains(strings.ToLower(doc.Content), strings.ToLower(req.Query)) {
				if enforceIsolation(tc, doc) {
					results = append(results, doc)
					if len(results) >= req.Limit {
						break
					}
				}
			}
		}
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// indexHandler allows tenants to index documents into their namespace
func indexHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPut {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	tc, err := extractTenantFromServiceAccount(r)
	if err != nil {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	var doc IndexDocument
	if err := json.NewDecoder(r.Body).Decode(&doc); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	// Force tenant_id to authenticated tenant
	doc.TenantID = tc.TenantID
	doc.IndexedAt = time.Now().UnixNano()

	targetNS := fmt.Sprintf("tenant-%s", tc.TenantID)

	store.mu.Lock()
	store.documents[targetNS] = append(store.documents[targetNS], doc)
	store.mu.Unlock()

	w.WriteHeader(http.StatusCreated)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	ctx := context.Background()
	_ = ctx

	mux := http.NewServeMux()
	mux.HandleFunc("/search", searchHandler)
	mux.HandleFunc("/index", indexHandler)
	mux.HandleFunc("/healthz", healthHandler)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	fmt.Println("Search indexing service starting on :8080")
	if err := server.ListenAndServe(); err != nil {
		fmt.Printf("Server error: %v\n", err)
	}
}
